def money(fen):
    return ("%.2f" % (fen / 100.0)).rstrip("0").rstrip(".")

def build_guide(city, cat, days, value_fen):
    dest = city[2]
    loc = city[1] + " · " + dest
    scene = city[3]
    sp, di = city[4], city[5]
    dur = {1:"一日轻旅行",2:"两日慢旅行",3:"三日深度游"}[days]
    pace = {"nearby":"上午出发，傍晚返程，节奏轻松","theme":"主题聚焦，边走边逛","province":"两日从容，核心景点不赶路","cross":"三日走透，山河全景一网打尽","guide":"行程自理，攻略给你完整路线图"}[cat]
    transit = "城市公共交通" if cat in ("nearby","theme") else ("攻略含大交通方案" if cat == "guide" else "全程大巴接送（已含）")
    scheds = []
    def add(d, t, title, desc, addr, tip):
        scheds.append({"dayNo":d,"time":t,"title":title,"description":desc,"addr":addr,"tip":tip})
    if days == 1:
        add(1,"08:30","集合出发","%s集合签到，核对行程信息后统一出发，车上讲解当日玩法与安全事项。"%city[1],"%s游客中心"%dest,"出发前一晚睡好，早餐别空腹")
        add(1,"09:30",sp[0][0],"首站直达%s，%s。建议停留%d分钟，跟着攻略动线走省一半时间。"%(sp[0][0],sp[0][2],int(sp[0][3]*0.8)),sp[0][1],"检票口集合不迷路")
        add(1,"12:00","地道午餐","正餐安排%s——人均约%d元，%s是本地招牌，点菜照着攻略走。"%(di[0][1],di[0][2],di[0][0]),di[0][3],"饭点人多，先落座再点单")
        add(1,"14:00",sp[1][0],"午后游览%s，%s。"%(sp[1][0],sp[1][2]),sp[1][1],"午后阳光强，防晒补水")
        add(1,"16:30",sp[2][0],"收官打卡%s，%s。随后自由活动，采购伴手礼。"%(sp[2][0],sp[2][2]),sp[2][1],"伴手礼认准正规商店")
        add(1,"17:30","返程","清点人数集合返程，结束充实一日；记得在App里晒出你的旅行战利品。","返程集合点","到集合点前先上个洗手间")
    elif days == 2:
        add(1,"08:30","出发赴%s"%city[1],"集合出发，大巴直达%s，车上介绍两日行程安排。"%dest,"集合城市出发","提前一晚收拾好行李")
        add(1,"11:00",sp[0][0],"抵达后首游%s，%s。"%(sp[0][0],sp[0][2]),sp[0][1],"直接入园，票务已含")
